The OnCalculate() function — the indicator’s “brain”
//+------------------------------------------------------------------+
//| Main calculation function                                        |
//+------------------------------------------------------------------+
int
OnCalculate
(
const
int
rates_total,
const
int
prev_calculated,
const
datetime
&time[],
const
double
&open[],
const
double
&high[],
const
double
&low[],
const
double
&close[],
const
long
&tick_volume[],
const
long
&volume[],
const
int
&spread[])
  {
if
(handleEnvelopes ==
INVALID_HANDLE
)
return
(
0
);
//--- Need at least InpLookbackBars+2 bars for extremum calculation
if
(rates_total < InpLookbackBars +
10
)
return
(
0
);
//--- Ensure Envelopes has enough data
if
(
BarsCalculated
(handleEnvelopes) < rates_total)
return
(
0
);
//--- Copy the Envelopes bands (both upper and lower)
if
(
CopyBuffer
(handleEnvelopes,
0
,
0
, rates_total, UpperBuffer) <=
0
)
return
(
0
);
if
(
CopyBuffer
(handleEnvelopes,
1
,
0
, rates_total, LowerBuffer) <=
0
)
return
(
0
);
//--- Set series orientation (0 = newest bar)
ArraySetAsSeries
(UpperBuffer,
true
);
ArraySetAsSeries
(LowerBuffer,
true
);
ArraySetAsSeries
(BuyArrowBuffer,
true
);
ArraySetAsSeries
(SellArrowBuffer,
true
);
ArraySetAsSeries
(open,
true
);
ArraySetAsSeries
(high,
true
);
ArraySetAsSeries
(low,
true
);
ArraySetAsSeries
(time,
true
);
//--- Determine the calculation range
// For performance reasons, we recalculate only the last InpMaxHistoryBars.
// But we must clear any arrows outside this range.
int
maxBars =
MathMin
(rates_total, InpMaxHistoryBars);
//--- Reset all arrow buffers before recalculating (to avoid ghost signals)
for
(
int
i =
0
; i < rates_total; i++)
     {
      BuyArrowBuffer[i]  =
EMPTY_VALUE
;
      SellArrowBuffer[i] =
EMPTY_VALUE
;
     }
//--- Main loop: calculate signals for all bars within the history limit
for
(
int
bar =
0
; bar < maxBars; bar++)
     {
//--- Need enough future bars for the extremum (bar+2 ... bar+InpLookbackBars)
if
(bar + InpLookbackBars +
2
>= rates_total)
continue
;
//--- Get current and previous open prices
double
currOpen = open[bar];
double
prevOpen = open[bar+
1
];
//--- Get Envelopes bands
double
upperEnv = UpperBuffer[bar];
double
lowerEnv = LowerBuffer[bar];
//--- Validate bands
if
(upperEnv <=
0
|| lowerEnv <=
0
|| upperEnv <= lowerEnv)
continue
;
//--- Calculate the Pardo extremum:
//    MAX(High[bar+2] ... High[bar+InpLookbackBars])
//    MIN(Low[bar+2]  ... Low[bar+InpLookbackBars])
double
maxHigh = high[bar+
2
];
double
minLow  = low[bar+
2
];
for
(
int
i =
2
; i <= InpLookbackBars; i++)
        {
int
idx = bar + i;
if
(idx >= rates_total)
break
;
if
(high[idx] > maxHigh) maxHigh = high[idx];
if
(low[idx]  < minLow)  minLow  = low[idx];
        }
//--- BUY signal conditions:
//    1. OPEN price above the UPPER band
//    2. Trend filter: current OPEN &gt; previous OPEN
//    3. Pardo breakout: current OPEN &gt; maxHigh of lookback bars
if
(currOpen > upperEnv)
        {
if
(currOpen > prevOpen && currOpen > maxHigh)
           {
// Place the BUY arrow slightly below the OPEN price
double
arrowPrice = currOpen - (InpArrowOffset *
_Point
);
            BuyArrowBuffer[bar] = arrowPrice;
           }
        }
//--- SELL signal conditions:
//    1. OPEN price below the LOWER band
//    2. Trend filter: current OPEN &lt; previous OPEN
//    3. Pardo breakout: current OPEN &lt; minLow of lookback bars
else
if
(currOpen < lowerEnv)
        {
if
(currOpen < prevOpen && currOpen < minLow)
           {
// Place the SELL arrow slightly above the OPEN price
double
arrowPrice = currOpen + (InpArrowOffset *
_Point
);
            SellArrowBuffer[bar] = arrowPrice;
           }
        }
//--- If the price is inside the channel -&gt; no signal (already cleared by the reset)
}
//--- Optional: log on new bar (commented out to prevent spam)
datetime
currentBarTime = time[
0
];
if
(currentBarTime != lastBarTime)
     {
      lastBarTime = currentBarTime;
// Uncomment for debugging:
// Print("New bar: ", TimeToString(currentBarTime), " | Total bars: ", rates_total);
}
return
(rates_total);
  }
